content.script:

/**
 * Prints a reverse right-angled triangle pattern of increasing numbers with n rows.
 * @param {number} n - The number of rows in the triangle.
 * Example: For n = 5, the output will be:
    5 5 5 5 5
    4 4 4 4
    3 3 3
    2 2
    1
 */
function printReverseRightAngledTriangle(n) {
    for (let i = n; i >= 1; i--) {
        let row = "";
        for (let j = 1; j <= i; j++) {
            row += i + " ";
        }
        console.log(row);
    }
}

printReverseRightAngledTriangle(5);
